package com.aqss.backend.entity;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;
import lombok.AllArgsConstructor;
import lombok.EqualsAndHashCode;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;

import java.io.Serializable;
import java.time.Instant;

/**
 * Composite primary key of {@code telemetry_data}: {@code (id, recorded_at)}.
 *
 * <p>The partition key ({@code recorded_at}) must be part of the PK. The {@code id} part is a
 * {@code BIGSERIAL} default filled by the database on INSERT, so the field is never generated by
 * JPA (writes go through a JdbcTemplate batch) — only used for entity identity on reads.
 */
@Embeddable
@Getter
@Setter
@NoArgsConstructor
@AllArgsConstructor
@EqualsAndHashCode
public class TelemetryDataId implements Serializable {

    @Column(name = "id")
    private Long id;

    @Column(name = "recorded_at", nullable = false)
    private Instant recordedAt;
}
